set -e
T=$(mktemp -d); S=$(mktemp -d)/state; BOT=<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/ours-g3-1/bot.mjs
cat > $T/check.mjs <<EOF
import { recordUnsubscribe, recordResubscribe, mayEmail } from '$BOT';
import { readdirSync, readFileSync } from 'node:fs';
const assert = (c, m) => { if (!c) { console.error('FAIL', m); process.exitCode = 1; } else console.log('ok', m); };
const now = new Date('2026-10-22T12:00:00Z');
const mk = (to, kind='marketing') => ({ to, kind });
const mode = process.argv[2];
if (mode === 'worker') {
  // N concurrent workers each record one unsubscribe for the same person at distinct times
  const i = Number(process.argv[3]);
  await recordUnsubscribe('"Jo" <' + (i%2 ? 'Jo.Hn+tag'+i : 'JOHN') + '@GMAIL.com>', new Date(Date.UTC(2026,9,1,0,0,i)));
  process.exit(0);
}
// 1. fresh address, marketing allowed; transactional allowed
assert(JSON.stringify(await mayEmail(mk('new@example.com'), now)) === '{"allowed":true,"reason":null}', 'fresh marketing allowed');
// 2. unsubscribe via header form and gmail alias blocks the canonical address
await recordUnsubscribe('"John D" <<EMAIL>>', new Date('2026-10-20T10:00:00Z'));
let r = await mayEmail(mk('<EMAIL>'), now);
assert(!r.allowed && r.reason === 'unsubscribed', 'gmail alias unsubscribe blocks marketing: ' + JSON.stringify(r));
r = await mayEmail(mk('<EMAIL>', 'transactional'), now);
assert(r.allowed, 'transactional still allowed after unsubscribe');
// 3. late, older resubscribe does not undo a newer unsubscribe
await recordResubscribe('<EMAIL>', new Date('2026-10-19T10:00:00Z'));
r = await mayEmail(mk('<EMAIL>'), now);
assert(!r.allowed, 'older resubscribe (arrived late) does not clear newer unsubscribe');
// 4. newer deliberate resubscribe clears it
await recordResubscribe('<EMAIL>', new Date('2026-10-21T10:00:00Z'));
r = await mayEmail(mk('<EMAIL>'), now);
assert(r.allowed, 'newer resubscribe clears unsubscribe');
// 5. unsubscribe arriving late but older than resubscribe stays cleared
await recordUnsubscribe('<EMAIL>', new Date('2026-10-18T10:00:00Z'));
r = await mayEmail(mk('<EMAIL>'), now);
assert(r.allowed, 'late older unsubscribe does not override newer resubscribe');
// 6. non-gmail: plus-tag is a different address, not the same person
await recordUnsubscribe('a+x@example.com', new Date('2026-10-20T00:00:00Z'));
assert((await mayEmail(mk('a@example.com'), now)).allowed, 'non-gmail plus-tag not merged');
assert(!(await mayEmail(mk('a+x@example.com'), now)).allowed, 'exact non-gmail address blocked');
// 7. invalid inputs
assert((await mayEmail(mk('not-an-address'), now)).reason === 'invalid_recipient', 'invalid recipient');
assert((await mayEmail(mk('x@example.com', 'bulk'), now)).reason === 'unknown_kind', 'unknown kind');
assert((await mayEmail(mk('x@example.com'), 'nope')).reason === 'invalid_time', 'invalid now');
let threw = false; try { await recordUnsubscribe('bad', new Date()); } catch { threw = true; }
assert(threw, 'recordUnsubscribe rejects invalid address');
// 8. restart: a fresh module instance with same STATE_DIR sees the state
const { mayEmail: again } = await import('$BOT?restart=1');
assert(!(await again(mk('a+x@example.com'), now)).allowed, 'state survives restart (fresh import)');
console.log('files:', readdirSync(process.env.STATE_DIR + '/suppression').length);
EOF
export STATE_DIR=$S
node $T/check.mjs main
# concurrency: 20 workers at once against the same person
for i in $(seq 0 19); do node $T/check.mjs worker $i & done; wait
node -e "
const fs=require('fs');const d='$S/suppression';const f=fs.readdirSync(d).filter(x=>{const t=fs.readFileSync(d+'/'+x,'utf8');return t.includes('<EMAIL>');});
const lines=fs.readFileSync(d+'/'+f[0],'utf8').split('\n').filter(Boolean).map(JSON.parse);
console.log('concurrent events written:',lines.length,'(expect 20 unsub + earlier 5)');
"
node -e "import('$BOT').then(async m=>{console.log('after concurrent run:', JSON.stringify(await m.mayEmail({to:'<EMAIL>',kind:'marketing'}, new Date())));})" </dev/null
# state unavailable -> fail closed for marketing
STATE_DIR=/dev/null/x node -e "import('$BOT').then(async m=>console.log('state broken:', JSON.stringify(await m.mayEmail({to:'z@example.com',kind:'marketing'}, new Date()))))"
